mapper.update:
UPDATE forum_resources
SET retired_at=#{retiredAt}
WHERE id=#{id}

UPDATE forum_resources
SET state='EXPIRED'
WHERE id=#{id}

UPDATE forum_resources
SET expires_at=#{expiresAt}
WHERE id=#{id}

UPDATE forum_resources
SET processing_claim=#{claim},claim_until=#{claimUntil}
WHERE id=#{id} AND state='PROCESSING' AND (claim_until IS NULL OR claim_until<#{now})

UPDATE forum_resources
SET state='READY',duration_seconds=#{duration},expires_at=#{expiresAt},claim_until=NULL
WHERE id=#{id} AND processing_claim=#{claim}

UPDATE forum_resources
SET state='FAILED',error_code=#{code},expires_at=#{expiresAt},claim_until=NULL
WHERE id=#{id} AND processing_claim=#{claim}
